package com.onlinelearning.model;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(uniqueConstraints=@UniqueConstraint(columnNames={"student_id","course_id"})) public class Enrollment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne private User student; @ManyToOne private Course course; private LocalDateTime enrolledAt=LocalDateTime.now(); private int progress; public Enrollment(){} public Enrollment(User s,Course c){student=s;course=c;} public Long getId(){return id;} public User getStudent(){return student;} public Course getCourse(){return course;} public LocalDateTime getEnrolledAt(){return enrolledAt;} public int getProgress(){return progress;} public void setProgress(int p){progress=Math.max(0,Math.min(100,p));} }
